def resolve_timeout(value):
    if value is None:
        return 30       # caller omitted it
    if value < 0:
        raise ValueError("timeout cannot be negative")
    return value        # zero is valid

for supplied in (None, 0, 5):
    print(supplied, "->", resolve_timeout(supplied))

# None -> 30
# 0 -> 0
# 5 -> 5
```
